{
  "explanation_fr": "Une alimentation saine est essentielle pour maintenir et guérir notre corps. Les bons aliments nous fournissent les vitamines, minéraux et nutriments nécessaires pour renforcer notre système immunitaire et accélérer le processus de guérison. En consommant des fruits, des légumes, des protéines maigres et des grains entiers, nous donnons à notre organisme les outils dont il a besoin pour combattre les maladies et réparer les tissus endommagés. Une mauvaise alimentation peut, au contraire, affaiblir nos défenses naturelles et ralentir la récupération. C'est pourquoi il est crucial de choisir des produits sains et équilibrés pour maintenir notre corps en bonne santé et favoriser sa capacité d'auto-guérison."
}

import java.io.File;
import java.io.FileInputStream;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecureFileDownloadServlet extends HttpServlet {
    private static final String DOCUMENTS_DIR = "/app/documents/";

    protected void doGet(HttpServletRequest request, HttpServletResponse response) {
        try {
            String fileName = request.getParameter("file");

            // Secure: Normalize path and validate it's within allowed directory
            Path requestedPath = Paths.get(DOCUMENTS_DIR, fileName).normalize();
            if (!requestedPath.startsWith(DOCUMENTS_DIR)) {
                response.sendError(HttpServletResponse.SC_FORBIDDEN);
                return;
            }

            File file = requestedPath.toFile();
            // Additional security check
            if (!file.exists() || !file.isFile()) {
                response.sendError(HttpServletResponse.SC_NOT_FOUND);
                return;
            }

            FileInputStream fis = new FileInputStream(file);
            byte[] buffer = new byte[4096];
            int bytesRead;

            while ((bytesRead = fis.read(buffer)) != -1) {
                response.getOutputStream().write(buffer, 0, bytesRead);
            }
            fis.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
